const DEMO_PLAYLISTS = [
  { name: 'Study Session', description: 'Soft beats and piano for deep focus.', songs: [0, 4, 1, 11, 5] },
  { name: 'Sunday Jazz Brunch', description: 'Brushes, upright bass and a little sax.', songs: [2, 3, 13, 10] },
];

/**
 * Insert the demo data.
 * @param {import('node:sqlite').DatabaseSync} db
 * @param {{ reset?: boolean, demoPassword?: string }} options
 *   reset: wipe users/songs/playlists/feedback first; otherwise skip if songs already exist.
 * @returns {Promise<{ seeded: boolean, songs?: number }>}
 */
export async function seedDemoData(db, { reset = false, demoPassword = 'myousik-demo-1' } = {}) {
  if (!reset && db.prepare('SELECT COUNT(*) AS n FROM songs').get().n > 0) return { seeded: false };

  // Hash before opening the transaction (scrypt is async; transactions here are sync).
  const { salt, hash } = await hashPassword(demoPassword);

  transaction(db, () => {
    if (reset) {
      for (const table of ['playlist_songs', 'playlists', 'songs', 'sessions', 'feedback', 'users']) {
        db.exec(`DELETE FROM ${table}`);
      }
    }
    const demo = db.prepare('INSERT INTO users (username, password_hash, password_salt) VALUES (?, ?, ?) RETURNING id')
      .get(DEMO_USERNAME, hash, salt);

    const insertSong = db.prepare(`
      INSERT INTO songs (title, artist, album, genre, duration_sec, year, cover_url, audio_url, created_by)
      VALUES (:title, :artist, :album, :genre, :duration_sec, :year, :cover_url, :audio_url, :created_by)`);
    const songIds = DEMO_SONGS.map((song) => Number(insertSong.run({ ...song, created_by: demo.id }).lastInsertRowid));

    const insertPlaylist = db.prepare('INSERT INTO playlists (user_id, name, description) VALUES (?, ?, ?)');
    const insertEntry = db.prepare('INSERT INTO playlist_songs (playlist_id, song_id, position) VALUES (?, ?, ?)');
    for (const playlist of DEMO_PLAYLISTS) {
      const { lastInsertRowid: playlistId } = insertPlaylist.run(demo.id, playlist.name, playlist.description);
      playlist.songs.forEach((songIndex, position) => insertEntry.run(playlistId, songIds[songIndex], position));
    }
  });

  return { seeded: true, songs: DEMO_SONGS.length };
}
